9	import { MessageStatus as Status, type Message, type QAItem } from "@/lib/type";
10	import { callAI, type CallConfig, type AICallContext } from "@/hooks/useAICall";
11	import { compareQAIds, parseContactInfo } from "@/hooks/chatUtils";
