271	/**
272	 * 顯示查詢方式選擇，用於"都不是我要問的，重新查詢"按鈕
273	 */
274	function showQueryModeSelection(question: string) {
275	  const messageIndex = addUserMessage("都不是我要問的，重新查詢");
276	
277	  // 顯示系統消息
278	  messages.value[messageIndex][1] = {
279	    role: Role.Assistant,
280	    content: "你想用哪種方式查詢呢？",
281	    timestamp: Date.now(),
282	    status: Status.End,
283	    question,
284	  };
285	  toChatBottom({ behavior: "smooth" });
286	}
