305	/**
306	 * 顯示 QA 直接答案
307	 * 用於點擊 QA 列表中的問題
308	 */
309	async function showQADirectAnswer(qa: QAItem) {
310	  const userContent =
311	    qa.type === "organizer"
312	      ? `給我以下問題的承辦單位：${qa.question}`
313	      : qa.question;
314	  const messageIndex = addUserMessage(userContent);
315	
316	  // 顯示載入中
317	  messages.value[messageIndex][1] = {
318	    role: Role.Assistant,
319	    content: "吉吉鳥正在尋找答案中",
320	    timestamp: Date.now(),
321	    status: Status.Pending,
322	  };
323	  toChatBottom({ behavior: "smooth" });
324	
325	  // 模擬載入時間
326	  await new Promise((resolve) => setTimeout(resolve, 500));
327	
328	  // 顯示答案
329	  const contact = parseContactInfo(qa.tel, qa.email, qa.answer);
330	
331	  messages.value[messageIndex][1] = {
332	    role: Role.Assistant,
333	    content:
334	      contact.length > 0 ? "如需進一步，協助請聯絡以下負責單位" : qa.answer,
335	    timestamp: Date.now(),
336	    status: Status.End,
337	    contact: contact.length > 0 ? contact : undefined,
338	  };
339	
340	  toChatBottom({ behavior: "smooth" });
341	}
342	
343	// ==================== AI 調用 ====================
344	
345	/**
346	 * flowId=7（學習規劃探索助手）、flowId=8（未來教室設備支援助理）共用：
347	 * 把目前這一輪之前的完整對話紀錄轉成 Gemini 的 user/model 格式，讓後端組成多輪 contents 陣列，
348	 * 模型才能依對話紀錄自行判斷目前進度、延續前面討論的內容。
349	 */
350	function buildChatHistory(): { role: "user" | "model"; text: string }[] {
351	  return messages.value.slice(0, -1).flatMap((pair) =>
352	    pair
353	      .filter(
354	        (m) =>
355	          (m.role === Role.User || m.role === Role.Assistant) &&
356	          m.status !== Status.Error,
357	      )
358	      .map((m) => ({
359	        role: m.role === Role.User ? ("user" as const) : ("model" as const),
360	        text: m.content,
361	      })),
362	  );
363	}
364	
365	const HISTORY_FLOW_IDS = new Set(["7", "8"]);
366	
367	/**
368	 * 呼叫 AI，根據 flow 設定處理
369	 */
370	async function callAIWrapper(
371	  messageIndex: number,
372	  content: string,
373	  flowId?: string,
374	  loadingText?: string,
375	  image?: { mimeType: string; data: string },
376	) {
377	  const context: AICallContext = {
378	    messages,
379	    publicKey,
380	    fingerprint,
381	    jwtToken,
382	    route,
383	  };
384	
385	  // flow=7（學習規劃探索助手）用：網址帶 ?model=openai / ?model=claude 切換供應商，預設 gemini
386	  const modelParam = route.query.model?.toString();
387	
388	  // 1. 優先使用 route.query.flow（用於測試等場景）
389	  if (route.query.flow) {
390	    const flowIds = route.query.flow.toString().split(",");
391	    for (let index = 0; index < flowIds.length; index++) {
392	      const id = flowIds[index];
393	      const config: CallConfig = {
394	        content,
395	        flowId: id,
396	        loadingText,
397	        ...(HISTORY_FLOW_IDS.has(id) ? { history: buildChatHistory() } : {}),
398	        ...(image ? { image } : {}),
399	        ...(modelParam ? { model: modelParam } : {}),
400	      };
401	      await callAI(context, messageIndex, 1, config, id === "0");
402	    }
403	    return;
404	  }
405	
406	  // 2. 使用傳入的 flowId，或默認使用 "0"
407	  const finalFlowId = flowId || "0";
408	  const config: CallConfig = {
409	    content,
410	    flowId: finalFlowId,
411	    loadingText,
412	    ...(HISTORY_FLOW_IDS.has(finalFlowId)
413	      ? { history: buildChatHistory() }
414	      : {}),
415	    ...(image ? { image } : {}),
416	    ...(modelParam ? { model: modelParam } : {}),
417	  };
418	  await callAI(context, messageIndex, 1, config, finalFlowId === "0");
419	}
420	
421	provide("messages", messages);
422	provide("isPending", isPending);
423	provide("isTranscribing", isTranscribing);
424	provide("isUploading", isUploading);
425	provide("send", send);
426	provide("sendDirectAnswer", showQADirectAnswer);
427	provide("sendDirectToAI", showQueryModeSelection);
428	provide("sendMessageToAIWithMode", sendMessageToAIWithMode);
429	provide("handleAudioTranscription", handleAudioTranscriptionWrapper);
430	provide("handleFileUpload", handleFileUploadWrapper);
431	provide("selectedMode", selectedMode);
