204	type StreamAccumulator = {
205	  content: string;
206	  source: string;
207	  hasReceivedContent: boolean;
208	};
209	
210	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
211	function applyStreamPayload(
212	  payload: SseStreamPayload,
213	  acc: StreamAccumulator,
214	  context: AICallContext,
215	  mIdx: number,
216	  idx: number,
217	) {
218	  if (payload.error) throw new Error(payload.error);
219	
220	  if (payload.delta) {
221	    acc.content += payload.delta;
222	    acc.hasReceivedContent = true;
223	    context.messages.value[mIdx][idx] = {
224	      role: Role.Assistant,
225	      content: acc.content,
226	      timestamp: Date.now(),
227	      status: Status.Receiving,
228	    };
229	  }
230	
231	  if (payload.done) acc.source = payload.source ?? "";
232	}
