234	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
235	async function consumeSseStream(
236	  res: Response,
237	  context: AICallContext,
238	  mIdx: number,
239	  idx: number,
240	): Promise<StreamAccumulator> {
241	  const reader = res.body!.getReader();
242	  const decoder = new TextDecoder("utf-8");
243	  const bufferRef = { value: "" };
244	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
245	
246	  while (true) {
247	    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
248	    if (done) break;
249	    for (const payload of payloads) {
250	      applyStreamPayload(payload, acc, context, mIdx, idx);
251	    }
252	  }
253	
254	  return acc;
255	}
